import { initializeApp, getApps, getApp } from 'firebase/app';
import { getAuth, GoogleAuthProvider } from 'firebase/auth';
import { getFirestore } from 'firebase/firestore';
import firebaseConfigJson from '../../firebase-applet-config.json';

// Initialize Firebase using the configuration generated by AI Studio
const firebaseConfig = {
  apiKey: firebaseConfigJson.apiKey,
  authDomain: firebaseConfigJson.authDomain,
  projectId: firebaseConfigJson.projectId,
  storageBucket: firebaseConfigJson.storageBucket,
  messagingSenderId: firebaseConfigJson.messagingSenderId,
  appId: firebaseConfigJson.appId,
};

const app = getApps().length > 0 ? getApp() : initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = firebaseConfigJson.firestoreDatabaseId
  ? getFirestore(app, firebaseConfigJson.firestoreDatabaseId)
  : getFirestore(app);
const googleProvider = new GoogleAuthProvider();
googleProvider.addScope('https://www.googleapis.com/auth/calendar.events');
googleProvider.addScope('https://www.googleapis.com/auth/gmail.readonly');
googleProvider.setCustomParameters({
  prompt: 'consent',
});
const ACTIVE_GOOGLE_CLIENT_ID = '9311814120-afkmf0sribf0ok5j1723974ehuuildgo.apps.googleusercontent.com';
const DELETED_CLIENT_ID_PREFIX = '952797581548';

function resolveGoogleOAuthClientId() {
  const envId = import.meta.env?.VITE_GOOGLE_CLIENT_ID;
  if (envId && !envId.startsWith(DELETED_CLIENT_ID_PREFIX)) {
    return envId;
  }
  const configId = firebaseConfigJson.oAuthClientId;
  if (configId && !configId.startsWith(DELETED_CLIENT_ID_PREFIX)) {
    return configId;
  }
  return ACTIVE_GOOGLE_CLIENT_ID;
}

const googleOAuthClientId = resolveGoogleOAuthClientId();

export { app, auth, db, googleProvider, firebaseConfig, googleOAuthClientId, ACTIVE_GOOGLE_CLIENT_ID };
